<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">PAYMENT DETAIL</div><h1 class="mono"><?php echo e($payment->reference); ?></h1><p><?php echo e($payment->business->name); ?> · <?php echo e(strtoupper($payment->gateway)); ?></p></div><span class="badge <?php echo e($payment->status->value); ?>"><?php echo e(ucfirst($payment->status->value)); ?></span></div><div class="stats-grid three"><div class="stat-card"><div class="stat-label">Amount</div><div class="stat-value">₹<?php echo e(number_format($payment->amount,2)); ?></div></div><div class="stat-card"><div class="stat-label">Gateway Order</div><div class="stat-value small mono"><?php echo e($payment->gateway_order_id ?: '—'); ?></div></div><div class="stat-card"><div class="stat-label">Card</div><div class="stat-value small"><?php echo e($payment->card?->reference ?: '—'); ?></div></div></div><div class="panel"><div class="panel-head"><h3>Payment Timeline</h3></div><div class="timeline"><div class="done">Created <span><?php echo e($payment->created_at->format('d M Y H:i')); ?></span></div><div class="<?php echo e(in_array($payment->status->value,['pending','processing','successful'])?'done':''); ?>">Gateway Processing</div><div class="<?php echo e($payment->status->value==='successful'?'done':''); ?>">Server Verified</div><div class="<?php echo e($payment->status->value==='successful'?'done':''); ?>">Ledger Updated</div></div><?php if($payment->gateway==='mock'&&$payment->status->value!=='successful'): ?><form method="POST" action="<?php echo e(route('payments.mock-complete',$payment)); ?>"><?php echo csrf_field(); ?><button class="btn primary">Complete Mock Payment</button></form><?php endif; ?></div><?php $__env->stopSection(); ?>

